/**
 * De-whitened standard frame printed in rs1729/RS rs41/rs41.txt.
 * It originates from the project's 2014 RS41 capture, not from our encoder.
 */
export const RS41_REAL_FRAME_HEX =
  "";

/** Extended 518-byte worked frame from the same rs41.txt reference. */
export const RS41_EXTENDED_FRAME_HEX =
  "";

export function bytesFromHex(hex: string): Uint8Array {
  if (hex.length % 2 !== 0)
    throw new Error("Hex fixture must have an even length.");
  return Uint8Array.from(hex.match(/../g) ?? [], (value) =>
    Number.parseInt(value, 16),
  );
}

